fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // maxsplit is the number of splits, rsplitn expects number of parts
    let max_parts = (maxsplit as usize).saturating_add(1);

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting, return original string as single element vector
                vec![s]
            } else {
                // Perform right split with max_parts
                // rsplitn yields parts from right to left, so reverse to natural order
                let mut parts: Vec<String> = s.rsplitn(max_parts, &sep)
                    .map(|part| part.to_string())
                    .collect();
                parts.reverse();
                parts
            }
        })
        .collect()
}